using System;using System.IO;using InFalsusStudio.Core;using UnityEngine;
namespace InFalsusStudio.VideoRender {
 internal sealed class OfflineAudioSynthesizer:IDisposable {
  const int Block=16384;readonly RenderJob job;readonly AudioClip clip;readonly float volume;readonly double offset;readonly int hz,channels;readonly long total;long done;readonly float[] music,fx=new float[Block*2];readonly byte[] pcm=new byte[Block*4];readonly PcmKeySoundMixer mixer=new PcmKeySoundMixer();readonly PcmMixState state;readonly BinaryWriter file;
  internal float Progress{get{return (float)((double)done/total);}}
  internal OfflineAudioSynthesizer(RenderJob j,AudioClip c,float gain,double audioOffset,PcmSoundPlan plan,float master,float shot,float hold){job=j;clip=c;volume=gain;offset=audioOffset;hz=c?c.frequency:48000;channels=c?c.channels:2;total=(long)Math.Round(j.Seconds*hz);if(total<1||total*4>uint.MaxValue-44)throw new IOException("Audio exceeds the WAV 4 GiB limit");if(c&&(c.loadState!=AudioDataLoadState.Loaded||channels<1||channels>8))throw new IOException("Audio data is not decoded");music=new float[checked(((int)Math.Ceiling(Block*j.Rate)+3)*channels)];state=new PcmMixState(plan,j.Start,0,j.Rate,j.Start,j.End,master,shot,hold,j.Sounds);file=new BinaryWriter(new FileStream(j.TempAudio,FileMode.CreateNew,FileAccess.Write,FileShare.None));file.Write(System.Text.Encoding.ASCII.GetBytes("RIFF"));file.Write((uint)(36+total*4));file.Write(System.Text.Encoding.ASCII.GetBytes("WAVEfmt "));file.Write(16);file.Write((short)1);file.Write((short)2);file.Write(hz);file.Write(hz*4);file.Write((short)4);file.Write((short)16);file.Write(System.Text.Encoding.ASCII.GetBytes("data"));file.Write((uint)(total*4));}
  internal bool Step(){if(done>=total)return false;int count=(int)Math.Min(Block,total-done);double startSource=((job.Start+offset)*.001+(double)done/hz*job.Rate)*hz;int sourceBase=clip?(int)Math.Max(0,Math.Min(clip.samples-1,Math.Floor(startSource))):0;if(clip&&!InFalsusStudio.NativeEditorUI.NativeEditorUIPlugin.ReadRenderAudio(clip,music,sourceBase))throw new IOException("Cannot read music PCM");mixer.Render(fx,2,hz,(double)done/hz,state);
   for(int i=0;i<count;i++){double at=(double)(done+i)/hz,source=startSource+i*job.Rate;float fade=job.Fade?(float)Math.Max(0,Math.Min(1,Math.Min(at/.5,(job.Seconds-at)/.5))):1;for(int ch=0;ch<2;ch++){float value=0;if(clip&&source>=0&&source<clip.samples){double local=source-sourceBase;int a=(int)Math.Floor(local),b=Math.Min(a+1,Math.Min(music.Length/channels-1,clip.samples-sourceBase-1));float t=(float)(local-a);if(a>=0&&a<music.Length/channels)value=(music[a*channels+(channels==1?0:ch)]+(music[b*channels+(channels==1?0:ch)]-music[a*channels+(channels==1?0:ch)])*t)*volume;}value=(value+fx[i*2+ch])*fade;if(float.IsNaN(value)||float.IsInfinity(value))value=0;int sample=(int)Math.Round(Math.Max(-1,Math.Min(1,value))*32767);int n=(i*2+ch)*2;pcm[n]=(byte)sample;pcm[n+1]=(byte)(sample>>8);}}file.Write(pcm,0,count*4);done+=count;return done<total;}
  public void Dispose(){file.Dispose();}
 }
}
